const Engram = require('./engram');

// Instantiate the Thinking Engine
const engram = new Engram();

// Mock API Entry Point
async function requestApiEntry(req) {
  console.log("\n--- INCOMING BANK REQUEST ---");
  const result = await engram.processRequest(req);
  console.log("--- RESPONSE SENT ---");
  console.log(JSON.stringify(result, null, 2));
  console.log("-----------------------------\n");
}

// Test Cases
